// tb_boed_q16_core.v - Self-Checking IEEE 1364-2005 Testbench for boed_q16_core
// Reads N=64 bit-exact golden vectors from golden_vectors.mem generated by
// src/machine_control/fpga_boed_dsp.py (Exp140/Exp149).
//
// Each 256-bit line in golden_vectors.mem packs:
//   [255:224] f_init_hz          (signed 32-bit Hz)
//   [223:192] f_probe_hz         (signed 32-bit Hz)
//   [191:160] y_meas_q16         (signed Q16.16)
//   [159:128] inv_gamma_q24      (unsigned Q24)
//   [127:96]  inv_2var_q16       (signed Q16.16)
//   [95:80]   delta_fisher_q4    (unsigned Q4)
//   [79:64]   max_off_q4         (unsigned Q4)
//   [63:56]   step_idx           (unsigned 8-bit)
//   [55:48]   reset_prior_flag   (1 = reload Gaussian prior before step)
//   [47:32]   exp_std_q4         (expected unsigned Q4 std)
//   [31:0]    exp_mu_off_q8      (expected signed Q8 mu offset)
//
// Run with Icarus Verilog or Verilator:
//   iverilog -g2005 -o sim_boed boed_lut_rom.v boed_isqrt_cordic.v boed_q16_core.v tb_boed_q16_core.v
//   vvp sim_boed
`timescale 1ns/1ps

module tb_boed_q16_core;
    localparam integer N_VECTORS = 64;
    localparam integer N_BINS    = 1001;

    reg                clk;
    reg                rst_n;

    reg                sprt_start;
    reg                sprt_reset_llr;
    reg  signed [31:0] sprt_y_q16;
    reg  signed [31:0] sprt_half_sig_q16;
    reg  signed [31:0] sprt_scale_q16;
    reg  signed [31:0] sprt_thresh_q16;
    wire               sprt_done;
    wire               sprt_decision_valid;
    wire               sprt_donor_present;
    wire signed [31:0] sprt_llr_q16;

    reg                step_start;
    reg                prior_load_en;
    reg         [9:0]  prior_load_addr;
    reg  signed [31:0] prior_load_lp_q16;
    reg  signed [31:0] f_init_hz;
    reg  signed [31:0] f_probe_hz;
    reg  signed [31:0] y_meas_q16;
    reg         [31:0] inv_gamma_q24;
    reg  signed [31:0] inv_2var_q16;
    reg         [15:0] delta_fisher_q4;
    reg         [15:0] max_off_q4;
    reg         [7:0]  step_idx;

    wire               busy;
    wire               step_done;
    wire signed [31:0] mu_off_q8;
    wire        [15:0] std_q4;
    wire signed [31:0] next_probe_off_q8;
    wire        [15:0] cycle_count;

    // 250 MHz clock (4.0 ns period)
    initial clk = 1'b0;
    always #2 clk = ~clk;

    boed_q16_core dut (
        .clk                (clk),
        .rst_n              (rst_n),
        .sprt_start         (sprt_start),
        .sprt_reset_llr     (sprt_reset_llr),
        .sprt_y_q16         (sprt_y_q16),
        .sprt_half_sig_q16  (sprt_half_sig_q16),
        .sprt_scale_q16     (sprt_scale_q16),
        .sprt_thresh_q16    (sprt_thresh_q16),
        .sprt_done          (sprt_done),
        .sprt_decision_valid(sprt_decision_valid),
        .sprt_donor_present (sprt_donor_present),
        .sprt_llr_q16       (sprt_llr_q16),
        .step_start         (step_start),
        .prior_load_en      (prior_load_en),
        .prior_load_addr    (prior_load_addr),
        .prior_load_lp_q16  (prior_load_lp_q16),
        .f_init_hz          (f_init_hz),
        .f_probe_hz         (f_probe_hz),
        .y_meas_q16         (y_meas_q16),
        .inv_gamma_q24      (inv_gamma_q24),
        .inv_2var_q16       (inv_2var_q16),
        .delta_fisher_q4    (delta_fisher_q4),
        .max_off_q4         (max_off_q4),
        .step_idx           (step_idx),
        .busy               (busy),
        .step_done          (step_done),
        .mu_off_q8          (mu_off_q8),
        .std_q4             (std_q4),
        .next_probe_off_q8  (next_probe_off_q8),
        .cycle_count        (cycle_count)
    );

    reg [255:0] vec_mem [0:N_VECTORS-1];
    integer i, b, errors, cyc;
    reg [15:0] exp_std;
    reg signed [31:0] exp_mu;
    reg [7:0] reset_flag;
    integer df_hz;

    initial begin
        $readmemh("golden_vectors.mem", vec_mem);
        rst_n             = 1'b0;
        sprt_start        = 1'b0;
        sprt_reset_llr    = 1'b0;
        sprt_y_q16        = 32'sd0;
        sprt_half_sig_q16 = 32'sd0;
        sprt_scale_q16    = 32'sd0;
        sprt_thresh_q16   = 32'sd0;
        step_start        = 1'b0;
        prior_load_en     = 1'b0;
        prior_load_addr   = 10'd0;
        prior_load_lp_q16 = 32'sd0;
        f_init_hz         = 32'sd0;
        f_probe_hz        = 32'sd0;
        y_meas_q16        = 32'sd0;
        inv_gamma_q24     = 32'd0;
        inv_2var_q16      = 32'sd0;
        delta_fisher_q4   = 16'd0;
        max_off_q4        = 16'd0;
        step_idx          = 8'd0;
        errors            = 0;

        repeat (4) @(posedge clk);
        rst_n = 1'b1;
        @(posedge clk);

        for (i = 0; i < N_VECTORS; i = i + 1) begin
            f_init_hz       = vec_mem[i][255:224];
            f_probe_hz      = vec_mem[i][223:192];
            y_meas_q16      = vec_mem[i][191:160];
            inv_gamma_q24   = vec_mem[i][159:128];
            inv_2var_q16    = vec_mem[i][127:96];
            delta_fisher_q4 = vec_mem[i][95:80];
            max_off_q4      = vec_mem[i][79:64];
            step_idx        = vec_mem[i][63:56];
            reset_flag      = vec_mem[i][55:48];
            exp_std         = vec_mem[i][47:32];
            exp_mu          = vec_mem[i][31:0];

            // Reload Gaussian prior sigma=2000 Hz: round(-0.5*(10*df_bin/2000)^2 * 65536)
            // Exact 32-bit-safe integer identity: -((df_bin^2 * 1024 + 625) / 1250) (max num 2.56e8 < 2^31)
            if (reset_flag != 8'd0) begin
                for (b = 0; b < N_BINS; b = b + 1) begin
                    df_hz = b - 500;
                    prior_load_en     = 1'b1;
                    prior_load_addr   = b[9:0];
                    prior_load_lp_q16 = -(((df_hz * df_hz * 32'sd1024) + 32'sd625) / 32'sd1250);
                    @(posedge clk);
                end
                prior_load_en = 1'b0;
                @(posedge clk);
            end

            step_start = 1'b1;
            @(posedge clk);
            step_start = 1'b0;

            cyc = 0;
            while (!step_done && cyc < 700) begin
                @(posedge clk);
                cyc = cyc + 1;
            end

            if (cycle_count !== 16'd584) begin
                $display("FAIL vec %0d: cycle_count=%0d (expected 584)", i, cycle_count);
                errors = errors + 1;
            end
            if (mu_off_q8 !== exp_mu || std_q4 !== exp_std) begin
                $display("FAIL vec %0d: mu_off_q8=%0d (exp %0d), std_q4=%0d (exp %0d)",
                         i, mu_off_q8, exp_mu, std_q4, exp_std);
                errors = errors + 1;
            end
            @(posedge clk);
        end

        if (errors == 0)
            $display("PASS: All %0d golden vectors verified at 0 LSB / 584 cycles!", N_VECTORS);
        else
            $display("FAIL: %0d vector mismatches detected.", errors);
        $finish;
    end
endmodule
